    background-color: #f3f4f6;
}

/* Dialog Styles */
dialog {
    border: none;
    border-radius: 12px;
    padding: 0;
    box-shadow: var(--shadow-lg);
    max-width: 400px;
    width: calc(100% - 2rem);
    margin: auto;
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
}

.dialog-content {
    padding: 1.5rem;
}

dialog h2 {
    font-size: 1.25rem;
    margin-bottom: 0.75rem;
    color: var(--text-main);
}

dialog p {
    color: var(--text-muted);
