(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlPath = path.resolve('index.html');
  await page.goto('file://' + htmlPath);

  const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
  await page.addScriptTag({ content: axeSource });

  // Test both closed and open states
  console.log('--- Testing Closed State ---');
  const resultsClosed = await page.evaluate(async () => await window.axe.run());
  printViolations(resultsClosed);

  console.log('\n--- Testing Open State ---');
  await page.click('.trigger');
  const resultsOpen = await page.evaluate(async () => await window.axe.run());
  printViolations(resultsOpen);

  await browser.close();
})();

function printViolations(results) {
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  console.log(JSON.stringify(wcag.map(v => ({ id: v.id, impact: v.impact, nodes: v.nodes.length })), null, 2));
}

