 document.addEventListener('DOMContentLoaded', () => {
     const dialog = document.getElementById('delete-confirm');
     const trigger = document.querySelector('.trigger');
     const cancelBtn = document.getElementById('cancel-btn');
     const confirmDeleteBtn = document.getElementById('confirm-delete-btn');

     // Open dialog
     trigger.addEventListener('click', () => {
         dialog.showModal();
         // Focus the cancel button by default to prevent accidental deletion
         cancelBtn.focus();
     });

     // Close dialog on cancel
     cancelBtn.addEventListener('click', () => {
         dialog.close('cancel');
     });

     // Close dialog on confirm delete
     confirmDeleteBtn.addEventListener('click', () => {
         dialog.close('delete');
     });

     // Handle dialog close events
     dialog.addEventListener('close', () => {
         const result = dialog.returnValue;
         if (result === 'delete') {
             console.log('Image deleted from library.');
             // In a real app, you would perform the deletion logic here.
             alert('Image deleted (simulation)');
         } else {
             console.log('Deletion cancelled.');
         }

         // Focus is automatically restored to the trigger by showModal() 
         // when the dialog is closed.
     });

     // Close on click outside (optional but common)
     dialog.addEventListener('click', (event) => {
         if (event.target === dialog) {
             dialog.close('cancel');
         }
     });
 });

